var KCAL={ protein:4, carb:4, fat:9, alcohol:7 };
function computeMacros(totalKcal, pPct, cPct, fPct){
  return { proteinG: totalKcal*pPct/100/KCAL.protein,
           carbG:    totalKcal*cPct/100/KCAL.carb,
           fatG:     totalKcal*fPct/100/KCAL.fat };
}
function proteinRange(weightKg, lo, hi){ lo=(lo==null)?1.6:lo; hi=(hi==null)?2.2:hi; return {min:weightKg*lo, max:weightKg*hi}; }
function macrosFromWeight(weightKg, goal){ // goal: cut/bulk/maintain
  var perKg = (goal==='cut')?2.0 : (goal==='bulk')?2.2 : 1.8;
  var protein=weightKg*perKg;
  return { proteinG:protein, kcalFromProtein:protein*KCAL.protein };
}
var EXPORTS={ KCAL:KCAL, computeMacros:computeMacros, proteinRange:proteinRange, macrosFromWeight:macrosFromWeight };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MacrosForgePure = EXPORTS; }
